// Kiso design tokens, generated from tokens/tokens.json. Do not edit.

/// The opaque semantic colors of one Kiso theme, as sRGB.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Theme {
    /// App canvas. Surface role, never text.
    pub background: Rgb,
    /// Cards, panels, table rows. Surface role.
    pub surface: Rgb,
    /// Menus, popovers, dialogs. Surface role.
    pub elevated_surface: Rgb,
    /// Primary text. Text-eligible: passes WCAG AA 4.5:1 on background, surface and elevated-surface in both themes.
    pub foreground: Rgb,
    /// Secondary text, labels. Text-eligible: passes WCAG AA 4.5:1 on background, surface and elevated-surface in both themes.
    pub muted_foreground: Rgb,
    /// Large supporting text and non-text graphics only (>=3:1 on their surface). Never small text. On dark this is dark.450, because dark.500 misses 3:1 on the dark surfaces.
    pub subtle_foreground: Rgb,
    /// Dividers and input outlines. Non-text role.
    pub border: Rgb,
    /// Primary fill: primary buttons, solid badges, checked controls, the brand mark. Deep violet in both themes; on dark it is a dedicated fill and is not text-eligible, so ink roles (link, focus) take accent.base instead.
    pub primary: Rgb,
    /// Emphasis and highlight. Text-eligible: passes WCAG AA 4.5:1 on background, surface and elevated-surface in both themes.
    pub accent: Rgb,
    /// Positive state. Text-eligible: passes WCAG AA 4.5:1 on background, surface and elevated-surface in both themes.
    pub success: Rgb,
    /// Caution state. Text-eligible: passes WCAG AA 4.5:1 on background, surface and elevated-surface in both themes.
    pub warning: Rgb,
    /// Destructive or error state. Text-eligible: passes WCAG AA 4.5:1 on background, surface and elevated-surface in both themes.
    pub danger: Rgb,
    /// Neutral informational state. Text-eligible: passes WCAG AA 4.5:1 on background, surface and elevated-surface in both themes.
    pub info: Rgb,
    /// Focus ring. Non-text role. >=3:1 against background. The light ink: alias of accent.base in both themes.
    pub focus: Rgb,
    /// Disabled text and controls. Exempt from contrast minimums per WCAG 1.4.3.
    pub disabled: Rgb,
    /// Panel and card fill. Alias of surface, named for the component that owns it.
    pub card: Rgb,
    /// Text on card.
    pub card_foreground: Rgb,
    /// Menus, dialogs, command palette. Alias of elevated-surface.
    pub popover: Rgb,
    /// Text on popover.
    pub popover_foreground: Rgb,
    /// Recessed fill one step off card: table headers, card footers, segmented tracks. Surface role.
    pub muted: Rgb,
    /// Application shell navigation column. Sits below the canvas on dark, above it on light.
    pub sidebar: Rgb,
    /// Divider between sidebar and content.
    pub sidebar_border: Rgb,
    /// Emphasised line: hover outlines, switch tracks, chart gridlines, corner marks. Non-text role, >=3:1 on background, surface and elevated-surface in both themes. On dark this is dark.450, sharing the subtle-text step as neutral.500 does on light.
    pub border_strong: Rgb,
    /// Form control outline at rest.
    pub input: Rgb,
    /// Text and icons on a primary fill. Near-white on the deep violet fill in both themes. Passes AA on primary in both themes.
    pub primary_foreground: Rgb,
    /// Primary fill on hover - one step brighter than primary, keeping primary-foreground legible.
    pub primary_hover: Rgb,
    /// Inline and standalone links. The light ink: alias of accent.base in both themes, so links stay text-eligible where the primary fill is not.
    pub link: Rgb,
    /// Faintest accent tint: row hover, ghost-button hover. Non-text role.
    pub accent_surface: Rgb,
    /// Accent tint one step stronger. Non-text role.
    pub accent_surface_hover: Rgb,
    /// Selected row, active navigation item, highlighted palette result. One ramp step past accent-surface-hover, so a selected item and a hovered sibling never paint the same surface. Non-text role.
    pub selected: Rgb,
    /// Text on a selected row.
    pub selected_foreground: Rgb,
    /// Neutral button fill, range track, count badge. Non-text role.
    pub secondary: Rgb,
    /// Text on a secondary fill.
    pub secondary_foreground: Rgb,
    /// Secondary fill on hover. Non-text role.
    pub secondary_hover: Rgb,
    /// Focus ring, drag handle active state. Alias of focus, named for the property it sets.
    pub ring: Rgb,
    /// Fill of a disabled control. Exempt from contrast minimums per WCAG 1.4.3.
    pub disabled_surface: Rgb,
    /// Loading placeholder fill. Non-text role.
    pub skeleton: Rgb,
    /// Hatch stripe marking a region that is not data. One step off the surface it sits on — never raise it further, it is a texture, not a message.
    pub hatch: Rgb,
    /// Corner registration marks. Non-text role.
    pub corner_mark: Rgb,
    /// Text and icons on a danger fill. Inverts with the fill, like primary-foreground: white on the light-theme red, near-black on the dark-theme salmon.
    pub danger_foreground: Rgb,
    /// Success on a permanently dark surface (log view, terminal). Theme-invariant on purpose: the surface does not follow color-scheme, so neither can the text.
    pub success_on_dark: Rgb,
    /// Warning on a permanently dark surface (log view, terminal). Theme-invariant on purpose: the surface does not follow color-scheme, so neither can the text.
    pub warning_on_dark: Rgb,
    /// Danger on a permanently dark surface (log view, terminal). Theme-invariant on purpose: the surface does not follow color-scheme, so neither can the text.
    pub danger_on_dark: Rgb,
    /// Info on a permanently dark surface (log view, terminal). Theme-invariant on purpose: the surface does not follow color-scheme, so neither can the text.
    pub info_on_dark: Rgb,
    /// Categorical chart series 1. Identity only, never status. Pair with its numbered label, interactive highlighting, and exact values. Pinned to the violet ink: chart series do not follow the accent, so the palette stays distinguishable from the status series under every accent.
    pub chart_1: Rgb,
    /// Categorical chart series 2. Identity only, never status. Pair with its numbered label, interactive highlighting, and exact values.
    pub chart_2: Rgb,
    /// Categorical chart series 3. Identity only, never status. Pair with its numbered label, interactive highlighting, and exact values.
    pub chart_3: Rgb,
    /// Categorical chart series 4. Identity only, never status. Pair with its numbered label, interactive highlighting, and exact values.
    pub chart_4: Rgb,
    /// Categorical chart series 5. Identity only, never status. Pair with its numbered label, interactive highlighting, and exact values.
    pub chart_5: Rgb,
}

